class Solution:
    def maxBalancedShipments(self, weight):
        n = len(weight)
        dp = [0] * (n + 1)
        for i in range(n):
            dp[i + 1] = dp[i]
            mx = 0
            for j in range(i, -1, -1):
                mx = max(mx, weight[j])
                if mx > weight[i]:
                    dp[i + 1] = max(dp[i + 1], dp[j] + 1)
                    break  # dp non-decreasing: earlier starts only help, but nearest greater is enough
        return dp[n]

