class Solution {
public:
    int maxBalancedShipments(vector<int>& weight) {
        int n = weight.size();
        vector<int> dp(n + 1, 0);
        for (int i = 0; i < n; i++) {
            dp[i + 1] = dp[i];
            int mx = 0;
            for (int j = i; j >= 0; j--) {
                mx = max(mx, weight[j]);
                if (mx > weight[i]) { dp[i + 1] = max(dp[i + 1], dp[j] + 1); break; }
            }
        }
        return dp[n];
    }
};

