class Solution:
    def maxBalancedShipments(self, weight):
        n = len(weight)
        dp = [0] * (n + 1)
        stack = []
        for i, w in enumerate(weight):
            while stack and weight[stack[-1]] <= w:
                stack.pop()
            best = dp[i]
            if stack:
                best = max(best, dp[stack[-1]] + 1)
            dp[i + 1] = best
            stack.append(i)
        return dp[n]

