class Solution {
    public int maxBalancedShipments(int[] weight) {
        int n = weight.length;
        int[] dp = new int[n + 1];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && weight[st.peek()] <= weight[i]) st.pop();
            dp[i + 1] = st.isEmpty() ? dp[i] : Math.max(dp[i], dp[st.peek()] + 1);
            st.push(i);
        }
        return dp[n];
    }
}

